package com.logiplatform.model;

import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;

@Entity @Table(name="ocean_containers") public class OceanContainer { @Id @GeneratedValue UUID id; @Column(name="tenant_id",nullable=false,updatable=false) UUID tenantId; @Column(name="shipment_id") UUID shipmentId; @Column(name="container_number",nullable=false) String containerNumber; @Column(name="container_type",nullable=false) String containerType; String sealNumber; BigDecimal tareWeightKg,grossWeightKg,vgmWeightKg; @Column(name="temperature_setpoint_c") BigDecimal temperatureSetpointC; boolean vgmVerified; String status="PLANNED"; Instant createdAt=Instant.now(),updatedAt=Instant.now(); protected OceanContainer(){} public OceanContainer(UUID t,UUID s,String no,String type,String seal,BigDecimal gross,BigDecimal vgm){tenantId=t;shipmentId=s;containerNumber=no;containerType=type;sealNumber=seal;grossWeightKg=gross;vgmWeightKg=vgm;vgmVerified=vgm!=null;} public UUID getId(){return id;} public UUID getShipmentId(){return shipmentId;} public String getContainerNumber(){return containerNumber;} public String getContainerType(){return containerType;} public String getSealNumber(){return sealNumber;} public BigDecimal getGrossWeightKg(){return grossWeightKg;} public BigDecimal getVgmWeightKg(){return vgmWeightKg;} public boolean isVgmVerified(){return vgmVerified;} public String getStatus(){return status;} }
